import { init, EChartsType } from '../../src/echarts.all';

describe('vue-raw-instance', function () {

    let chart: EChartsType;

    beforeEach(function () {
        const el = document.createElement('div');
        el.style.cssText = 'width:500px;height:400px;';
        Object.defineProperty(el, 'clientWidth', { get() { return 500; } });
        Object.defineProperty(el, 'clientHeight', { get() { return 400; } });
        document.body.appendChild(el);
        chart = init(el);
    });

    afterEach(function () {
        chart && chart.dispose();
        document.body.innerHTML = '';
    });

    it('echarts instance is marked with __v_skip so Vue 3 treats it as raw', function () {
        expect((chart as any).__v_skip).toBe(true);
        // Instance methods still work.
        expect(function () {
            chart.setOption({
                xAxis: {},
                yAxis: {},
                series: [{ type: 'line', data: [1, 2, 3] }]
            });
        }).not.toThrow();
    });
});
